SELECT addDays(toDate(toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0)), throwIf(ifNull((toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) < toDate32('1970-01-01')) OR (toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) > toDate32('2149-06-06')), 0), 'typedhouse_date_out_of_range')) AS `effectiveAt`, sum(`__typedhouse_input`.`stock_index`) AS `stock_index` FROM (SELECT `effectiveAt`, `stock_index` FROM `metric_group_ots_component_indices` FINAL) AS `__typedhouse_input` GROUP BY addDays(toDate(toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0)), throwIf(ifNull((toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) < toDate32('1970-01-01')) OR (toStartOfWeek(toDate32(`__typedhouse_input`.`effectiveAt`), 0) > toDate32('2149-06-06')), 0), 'typedhouse_date_out_of_range')) SETTINGS enable_extended_results_for_datetime_functions = 1
